    1,
    'published',
    $json$[{"text":"Особиста інформація — це дані про тебе, які треба берегти. 🔒 Адреса, номер телефону, пароль — це відомості, які не можна надсилати будь-кому. Не все про себе варто повідомляти онлайн.","title":"Особиста інформація"},{"text":"🙂 Безпечно розповісти: улюблений колір, назву улюбленої казки чи гри.\n🔒 Приватне, що треба берегти: адресу, пароль, номер телефону.\n🙋 Якщо сумніваєшся — спершу запитай дорослого.","title":"Безпечне і приватне"},{"text":"Якщо хтось онлайн просить щось особисте — не відповідай поспіхом. Запам'ятай чотири кроки:\n⏸ зупинися\n🚫 не надсилай\n🙋 поклич дорослого\n🧠 поясни, що не впевнений(а)","title":"Коли просять зайве"},{"text":"Приватність — це не про страх, а про захист. 🛡 Коли ти бережеш свої дані, ти спокійніше і безпечніше користуєшся пристроями. Це навичка справжнього цифрового дослідника! 🤝","title":"Чому це важливо"}]$json$::jsonb,
    NULL,
    $json$[{"question":"Що з цього — приватна інформація?","options":["Улюблений колір","Домашня адреса","Назва улюбленої казки"],"correct":1,"explanation":"Адресу треба берегти — її не можна повідомляти незнайомцям онлайн."},{"question":"Хтось у грі просить твій пароль. Що робиш?","options":["Надсилаю, якщо ввічливо просять","Зупиняюся і кличу дорослого","Надсилаю тільки половину пароля"],"correct":1,"explanation":"Пароль не надсилають нікому. Зупинись, не надсилай, поклич дорослого."},{"question":"Ти не впевнений(а), чи можна щось написати онлайн. Як вчинити?","options":["Написати і подивитися, що буде","Спершу запитати дорослого","Написати, але маленькими літерами"],"correct":1,"explanation":"Правило просте: сумніваєшся — спершу запитай дорослого."}]$json$::jsonb
